using int64 = long long;
const int64 INF = (1LL << 62);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    int64 m;
    cin >> n >> m;

    // pos[i]: tray of cup i, where i=1 is the smallest, i=n the largest.
    // Encode A=0, B=1, C=2.
    vector<int> pos(n + 1);

    for (int t = 0; t < 3; ++t) {
        int k;
        cin >> k;
        vector<int> v(k);
        for (int i = 0; i < k; ++i) cin >> v[i];
        for (int x : v) pos[x] = t;
    }

    // dpA[i] = minimum moves to gather cups 1..i onto tray A
    // dpC[i] = minimum moves to gather cups 1..i onto tray C
    //
    // Since cup i is the largest among 1..i, to move it we must first gather
    // smaller cups 1..i-1 onto the opposite side (or same side if already free),
    // then move cup i, then gather smaller cups onto destination.
    //
    // Distances on line A-B-C:
    // d(A,A)=0 d(B,B)=0 d(C,C)=0
    // d(A,B)=1 d(B,C)=1 d(A,C)=2
    auto dist = [](int x, int y) -> int64 {
        return llabs(x - y);
    };

    vector<int64> dpA(n + 1, INF), dpC(n + 1, INF);
    dpA[0] = dpC[0] = 0;

    for (int i = 1; i <= n; ++i) {
        int p = pos[i];

        // To gather 1..i on A:
        // smaller cups 1..i-1 must end on C before moving cup i to A
        // then smaller cups move from C to A
        dpA[i] = dpC[i - 1] + dist(p, 0) + dpA[i - 1];

        // To gather 1..i on C:
        // smaller cups 1..i-1 must end on A before moving cup i to C
        // then smaller cups move from A to C
        dpC[i] = dpA[i - 1] + dist(p, 2) + dpC[i - 1];

        if (dpA[i] > INF / 2) dpA[i] = INF;
        if (dpC[i] > INF / 2) dpC[i] = INF;
    }

    int64 ans = min(dpA[n], dpC[n]);
    if (ans <= m) cout << ans << '\n';
    else cout << -1 << '\n';

    return 0;
}

