public class CupMover {

    // State representation: three stacks (as integers bitmasked for speed)
    // Since n <= 10, we can use bitmask per tray.
    // But for clarity, we use simple arrays.
    static int n;
    static int[] tray;
    // tray[i] = which tray cup i (0-indexed, 0=A,1=B,2=C) is on.
    // Cup 0 = smallest, cup n-1 = largest.

    static Map<String, Integer> dist;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        tray = new int[n];
        for (int i = 0; i < n; i++) {
            tray[i] = sc.next().charAt(0) - 'A';
        }
        int m = sc.nextInt();

        String start = encode(tray);
        dist = new HashMap<>();
        Queue<String> q = new LinkedList<>();
        q.add(start);
        dist.put(start, 0);

        while (!q.isEmpty()) {
            String cur = q.poll();
            int d = dist.get(cur);
            if (d == m) continue; // we don't need to go beyond m

            int[] curTray = decode(cur);

            // Find top cup on each tray (largest index on that tray)
            int[] top = new int[3];
            Arrays.fill(top, -1);
            for (int i = n-1; i >= 0; i--) {
                if (top[curTray[i]] == -1) {
                    top[curTray[i]] = i;
                }
            }

            // Try moves: A<->B, B<->C
            int[][] moves = {{0,1},{1,0},{1,2},{2,1}};
            for (int[] mv : moves) {
                int from = mv[0];
                int to = mv[1];
                if (top[from] == -1) continue; // nothing to move
                int cup = top[from];
                if (top[to] == -1 || cup < top[to]) { // can place
                    int[] nextTray = curTray.clone();
                    nextTray[cup] = to;
                    String next = encode(nextTray);
                    if (!dist.containsKey(next)) {
                        dist.put(next, d+1);
                        q.add(next);
                    }
                }
            }
        }

        // Check target states: all cups on A or all on C
        int[] allA = new int[n];
        Arrays.fill(allA, 0);
        int[] allC = new int[n];
        Arrays.fill(allC, 2);
        String targetA = encode(allA);
        String targetC = encode(allC);

        int ans = Integer.MAX_VALUE;
        if (dist.containsKey(targetA)) {
            ans = Math.min(ans, dist.get(targetA));
        }
        if (dist.containsKey(targetC)) {
            ans = Math.min(ans, dist.get(targetC));
        }
        if (ans <= m) {
            System.out.println(ans);
        } else {
            System.out.println(-1);
        }
    }

    static String encode(int[] arr) {
        StringBuilder sb = new StringBuilder();
        for (int x : arr) sb.append((char)('0' + x));
        return sb.toString();
    }

    static int[] decode(String s) {
        int[] arr = new int[s.length()];
        for (int i = 0; i < s.length(); i++) {
            arr[i] = s.charAt(i) - '0';
        }
        return arr;
    }
}

