public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static long[] pow3;

    // State encoding:
    // for cup i (0 = smallest, n-1 = largest), digit in base-3 tells its peg:
    // 0 = A, 1 = B, 2 = C
    //
    // Because on each peg cups are always ordered by size, a state is fully determined
    // by peg position of every cup.

    static long minMovesToTarget(int n, int[] pos, int targetPeg) {
        // Recursive formula:
        // Let largest cup be cup n-1 currently on peg p.
        // To move all cups 0..n-1 to target t:
        //
        // If p == t:
        //   just move smaller n-1 cups to t.
        //
        // Else:
        //   largest cup can move to adjacent peg only.
        //   Since direct A<->C is forbidden, path length between pegs is:
        //      dist(A,B)=1, dist(B,C)=1, dist(A,C)=2.
        //
        //   Before moving largest cup from p to next peg on path to t,
        //   all smaller cups must be gathered on the third peg.
        //   This gives a unique optimal recurrence.
        //
        // f(n, state, t):
        //   if n==0 return 0
        //   p = pos[n-1]
        //   if p==t: f(n-1, state, t)
        //   else if |p-t|==1:
        //       other = 3-p-t
        //       f(n-1, state, other) + 1 + fullMove(n-1, other, t)
        //   else (p and t are A/C):
        //       mid = 1
        //       other = 3-p-mid = opposite end
        //       f(n-1, state, t) + 1 + fullMove(n-1, t, p) + 1 + fullMove(n-1, p, t)
        //
        // But for A<->C path, since p!=t and middle is B, explicitly:
        //   move smaller to t, move largest p->B,
        //   move smaller t->p, move largest B->t,
        //   move smaller p->t.
        return solve(n, pos, targetPeg);
    }

    static long solve(int n, int[] pos, int target) {
        if (n == 0) return 0;
        int p = pos[n - 1];
        if (p == target) return solve(n - 1, pos, target);

        if (Math.abs(p - target) == 1) {
            int other = 3 - p - target;
            return solve(n - 1, pos, other) + 1 + fullMove(n - 1, other, target);
        } else {
            // p and target are 0 and 2
            int mid = 1;
            return solve(n - 1, pos, target)
                    + 1
                    + fullMove(n - 1, target, p)
                    + 1
                    + fullMove(n - 1, p, target);
        }
    }

    static long fullMove(int n, int from, int to) {
        // Minimum moves to move a full tower of n cups from peg from to peg to
        // with only adjacent moves allowed.
        // Recurrence:
        // adjacent: T(n)=2*T(n-1)+1
        // opposite ends: U(n)=3*U(n-1)+2, but can also be expressed through same recursion:
        // if |from-to|==1:
        //   F(n,adj)=F(n-1,other,to?) Actually:
        //   move n-1 from from to other-end,
        //   move largest,
        //   move n-1 from other-end to to
        // gives T(n)=U(n-1)+1+T(n-1)
        //
        // Easier: direct recursive definition.
        if (n == 0) return 0;
        if (Math.abs(from - to) == 1) {
            int other = 3 - from - to;
            return fullMove(n - 1, from, other) + 1 + fullMove(n - 1, other, to);
        } else {
            int mid = 1;
            return fullMove(n - 1, from, to) + 1 + fullMove(n - 1, to, from) + 1 + fullMove(n - 1, from, to);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n = fs.nextInt();
        long m = fs.nextLong();

        int[] pos = new int[n]; // pos[i]: peg of cup i, i=0 smallest ... n-1 largest

        // Input format assumption:
        // For each tray A, B, C:
        // k followed by k cup numbers listed from bottom to top or top to bottom?
        //
        // Since cups are uniquely sized 1..n and state only needs peg of each cup,
        // we just read all numbers and assign them to current peg.
        //
        // The order inside each tray is guaranteed valid by statement.
        for (int peg = 0; peg < 3; peg++) {
            int k = fs.nextInt();
            for (int i = 0; i < k; i++) {
                int cup = fs.nextInt();
                pos[cup - 1] = peg;
            }
        }

        long ansA = minMovesToTarget(n, pos, 0);
        long ansC = minMovesToTarget(n, pos, 2);
        long ans = Math.min(ansA, ansC);

        System.out.println(ans <= m ? ans : -1);
    }
}

