    // To move n cups from A to C (or C to A): need 3^n - 1 moves
    // To move n cups from A to B or B to C: need 2^n - 1 moves (standard)
    if (target == 1) { // tray B? Not needed, but for completeness
        return (1LL << n) - 1; // 2^n - 1
    } else { // A or C (ends)
        long long res = 1;
